import { copyFileSync, existsSync, readFileSync, readdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { desc, eq } from 'drizzle-orm';
import { games, gameVersions, users } from '@playloop/db';
import { extractManifest, validateGame } from '@playloop/gamekit';

type Db = {
  select: (...args: never[]) => never;
};

/**
 * Publish every generated seed game sitting in `.artifacts/seeds/*.html`.
 *
 * Called by the dev-db boot (`scripts/dev-db.ts`) so seeds generated by
 * `pnpm gen:seed` appear in the feed on the next `pnpm dev` — no second
 * database connection needed, which matters because the PGlite dev server
 * accepts exactly one.
 *
 * Idempotent: a seed whose title already exists is re-published as a new
 * version instead of creating a duplicate card.
 */
export async function publishPendingSeeds(
  db: any,
  opts: { seedsDir: string; artifactsDir: string; ownerHandle?: string; log?: (line: string) => void },
): Promise<{ published: number; skipped: number }> {
  const log = opts.log ?? (() => {});
  if (!existsSync(opts.seedsDir)) return { published: 0, skipped: 0 };

  const [owner] = await db.select().from(users).where(eq(users.handle, opts.ownerHandle ?? 'playloop')).limit(1);
  if (!owner) {
    log('[seeds] system user @playloop missing — skipping generated seeds');
    return { published: 0, skipped: 0 };
  }

  let published = 0;
  let skipped = 0;

  for (const file of readdirSync(opts.seedsDir).filter((f) => f.endsWith('.html'))) {
    const slug = file.replace(/\.html$/, '');
    const code = readFileSync(path.join(opts.seedsDir, file), 'utf8');

    const validation = validateGame(code);
    if (validation.errors.length > 0) {
      log(`[seeds] skip ${slug}: ${validation.errors.slice(0, 2).join('; ')}`);
      skipped += 1;
      continue;
    }
    const manifest = extractManifest(code);
    if (!manifest) {
      log(`[seeds] skip ${slug}: no pl-manifest`);
      skipped += 1;
      continue;
    }

    const sha = createHash('sha256').update(Buffer.from(code, 'utf8')).digest('hex');
    const bytes = Buffer.byteLength(code);
    copyFileSync(path.join(opts.seedsDir, file), path.join(opts.artifactsDir, `${sha}.html`));

    const existing = await db.select({ id: games.id }).from(games).where(eq(games.title, manifest.title)).limit(1);
    let gameId: string | undefined = existing[0]?.id;
    let nextVersionNo = 1;

    if (gameId) {
      // Re-publishing the same artifact must be a no-op, otherwise every boot
      // inserts version 1 again and trips the (game_id, version_no) unique key.
      const [latest] = await db
        .select({ versionNo: gameVersions.versionNo, sha: gameVersions.artifactSha256 })
        .from(gameVersions)
        .where(eq(gameVersions.gameId, gameId))
        .orderBy(desc(gameVersions.versionNo))
        .limit(1);
      if (latest?.sha === sha) {
        log(`[seeds] “${manifest.title}” already up to date`);
        continue;
      }
      nextVersionNo = (latest?.versionNo ?? 0) + 1;
    }

    if (!gameId) {
      const [created] = await db
        .insert(games)
        .values({
          creatorId: owner.id,
          title: manifest.title,
          description: manifest.description,
          tags: manifest.tags,
          status: 'published',
          moderation: 'approved',
          publishedAt: new Date(),
        })
        .returning({ id: games.id });
      gameId = created!.id;
      log(`[seeds] published “${manifest.title}” (${bytes} bytes)`);
      published += 1;
    } else {
      await db
        .update(games)
        .set({ description: manifest.description, tags: manifest.tags, status: 'published', deletedAt: null })
        .where(eq(games.id, gameId));
      log(`[seeds] refreshed “${manifest.title}”`);
      published += 1;
    }

    const [version] = await db
      .insert(gameVersions)
      .values({
        gameId,
        versionNo: nextVersionNo,
        artifactSha256: sha,
        artifactBytes: bytes,
        artifactKey: `artifacts/${sha}.html`,
        manifest,
        createdBy: 'ai',
      })
      .returning({ id: gameVersions.id });

    await db.update(games).set({ publishedVersionId: version!.id }).where(eq(games.id, gameId));
  }

  return { published, skipped };
}
